import{_ as a,o as n,c as p,a2 as o}from"./chunks/framework.BXzK3EA4.js";const s="/assets/vps%E4%BA%A7%E5%93%81%E7%AE%A1%E7%90%86.bSECUq8l.png",r="/assets/%E6%89%BE%E5%88%B0%E7%9B%AE%E6%A0%87vps.BO0-C5Ba.png",i="/assets/vpsvnc11.DAQldv7S.png",l="/assets/%E8%BE%93%E5%85%A5%E8%BF%9E%E6%8E%A5%E5%AF%86%E7%A0%8111.8iy66dCH.png",e="/assets/%E8%BF%9C%E7%A8%8B%E7%99%BB%E5%BD%95.D3D7Bwxv.png",g="/assets/%E8%BF%9C%E7%A8%8Bip%E8%BF%9E%E6%8E%A5.CuQAbKHx.png",c="/assets/%E7%8B%AC%E6%9C%8D%E5%AF%86%E7%A0%81.B7hYQis7.png",d="/assets/vps%E6%8E%A7%E5%88%B6%E5%8F%B0.rCjfc46C.png",h="/assets/vpsvnc.xOqjNfja.png",E="/assets/application12.CtG-3KW6.png",m="/assets/%E5%91%BD%E4%BB%A4%E8%A1%8C11.BzWvznq7.png",_="/assets/%E8%BF%9E%E6%8E%A5%E6%88%90%E5%8A%9F11.CGLsIGjR.png",S="/assets/%E5%88%9B%E5%BB%BA%E8%BF%9C%E7%A8%8B%E8%BF%9E%E6%8E%A5.COQb-rvk.png",u="/assets/%E8%BF%9C%E7%A8%8B%E7%99%BB%E5%BD%95%E6%88%90%E5%8A%9F11.BzAgzfWR.png",q=JSON.parse('{"title":"登录 VPS","description":"","frontmatter":{"title":"登录 VPS"},"headers":[],"relativePath":"vps/quickstart/login.md","filePath":"vps/quickstart/login.md","lastUpdated":1793696072000}'),B={name:"vps/quickstart/login.md"};function P(V,t,v,A,b,C){return n(),p("div",null,[...t[0]||(t[0]=[o('<p>根据购买时选择的 VPS 操作系统类型的不同，您可以选择 Windows 登录方式或 Linux 登录方式。</p><hr><h3 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h3><p>已购买并开通 VPS 。详细内容可参考<a href="./purchase.html">购买 VPS</a>。</p><hr><h3 id="登录-windows-vps" tabindex="-1">登录 Windows VPS <a class="header-anchor" href="#登录-windows-vps" aria-label="Permalink to &quot;登录 Windows VPS&quot;">​</a></h3><p>Windows VPS 支持通过控制台 VNC 登录和远程桌面登录。</p><h4 id="方式-1-通过控制台-vnc-登录" tabindex="-1">方式 1：通过控制台 VNC 登录 <a class="header-anchor" href="#方式-1-通过控制台-vnc-登录" aria-label="Permalink to &quot;方式 1：通过控制台 VNC 登录&quot;">​</a></h4><p>控制台 VNC 是连接 VPS 的可视化操作界面，可进行系统操作、文件管理等操作。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在控制台左侧导航<strong>产品管理</strong>区域，单击 <strong>VPS</strong>，进入<strong>我的产品与服务</strong>页面。此页面默认展示当前区域全部已购买的 VPS 。</p><p><img src="'+s+'" alt="vps产品管理.png"></p></li><li><p>你可以通过地区或状态查找目标VPS 。单击<strong>产品/服务</strong>名称，进入此 VPS 的产品详情页面。</p><p><img src="'+r+'" alt="找到目标vps.png"></p></li><li><p>单击 <strong>VNC</strong>，进入 VNC 连接面板。</p><p><img src="'+i+'" alt="vpsvnc11.png"></p></li><li><p>在 Windows 系统登录界面，输入服务器密码，完成登录。</p><p><img src="'+l+'" alt="输入连接密码11.png"></p></li></ol><h4 id="方式-2-使用远程桌面登录" tabindex="-1">方式 2：使用远程桌面登录 <a class="header-anchor" href="#方式-2-使用远程桌面登录" aria-label="Permalink to &quot;方式 2：使用远程桌面登录&quot;">​</a></h4><p>本例以 Windows 系统自带的远程桌面连接应用作简要说明。</p><ol><li><p>在本地 Windows 电脑上，按 <strong>Win + R</strong> 键打开<strong>运行</strong>对话框，输入 <strong>mstsc</strong>，单击<strong>确定</strong>，进入<strong>远程桌面连接</strong>页面。</p><p><img src="'+e+'" alt="远程登录.png"></p></li><li><p>在<strong>计算机</strong>输入框中，输入 Windows 服务器的公网 IP 地址，如：192.168.1.1。默认的远程桌面端口默认为 3389，如果服务器修改了默认的端口，则需在 IP 加上冒号和本机端口号，如：192.168.1.1:3390。</p><p><img src="'+g+'" alt="远程ip连接.png"></p></li><li><p>单击<strong>连接</strong>。</p></li><li><p>在弹出的窗口中，输入服务器的<strong>管理员账号</strong>（通常是 Administrator）和对应的密码，单击<strong>确定</strong>。</p><p><img src="'+c+'" alt="独服密码.png"></p></li></ol><hr><h3 id="登录-linux-vps" tabindex="-1">登录 Linux VPS <a class="header-anchor" href="#登录-linux-vps" aria-label="Permalink to &quot;登录 Linux VPS&quot;">​</a></h3><p>登录 Linux VPS 包含使用控制台 VNC 功能登录和使用 SSH 客户端远程登录两种方式。</p><h4 id="方式-1-通过控制台-vnc-功能连接服务器" tabindex="-1">方式 1：通过控制台 VNC 功能连接服务器 <a class="header-anchor" href="#方式-1-通过控制台-vnc-功能连接服务器" aria-label="Permalink to &quot;方式 1：通过控制台 VNC 功能连接服务器&quot;">​</a></h4><p>控制台 VNC 是连接 VPS 的可视化操作界面，可进行系统操作、文件管理等操作。</p><ol><li><p>登录 <a href="https://billing.raksmart.com/whmcs/clientarea.php?language=chinese-cn" target="_blank" rel="noreferrer">RakSmart 控制台</a>。</p></li><li><p>在顶部导航右侧，单击<strong>控制台</strong>，进入控制台<strong>客户中心</strong>页面。</p><p><img src="'+d+'" alt="vps控制台.png"></p></li><li><p>在左侧导航<strong>产品管理</strong>区域，单击 <strong>VPS</strong>，进入<strong>我的产品与服务</strong>页面。</p><p><img src="'+s+'" alt="vps产品管理.png"></p></li><li><p>你可以通过<strong>地区</strong>或<strong>状态</strong>查找目标VPS 。单击<strong>产品/服务</strong>名称，进入此 VPS 的<strong>管理产品</strong>页面。</p><p><img src="'+r+'" alt="找到目标vps.png"></p></li><li><p>单击 <strong>VNC</strong>。</p><p><img src="'+h+'" alt="vpsvnc.png"></p></li><li><p>在确认运行页面勾选确认信息，单击 <strong>Run</strong>。进入连接命令行界面。</p><p><img src="'+E+'" alt="application12.png"></p></li><li><p>在命令行页面输入用户名和密码。用户名默认为 root，密码可查看购买 VPS 时 RakSmart 发送的产品信息邮件。</p><p><img src="'+m+'" alt="命令行11.png"></p></li><li><p>连接服务器成功。</p><p><img src="'+_+'" alt="连接成功11.png"></p></li></ol><h4 id="方式-2-使用-ssh-客户端远程连接-vps" tabindex="-1">方式 2：使用 SSH 客户端远程连接 VPS <a class="header-anchor" href="#方式-2-使用-ssh-客户端远程连接-vps" aria-label="Permalink to &quot;方式 2：使用 SSH 客户端远程连接 VPS&quot;">​</a></h4><p>此方式是指使用 SSH 客户端工具，在本地设备上通过网络远程访问 VPS ，登录系统进行命令行操作的过程。</p><h5 id="前提条件-1" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件-1" aria-label="Permalink to &quot;前提条件&quot;">​</a></h5><p>本地设备已安装 SSH 客户端：</p><ul><li>本地设备为 Windows 系统时可使用 PuTTY、Xshell；</li><li>本地设备为 Mac/Linux 系统时可使用自带终端。</li></ul><h5 id="操作步骤" tabindex="-1">操作步骤 <a class="header-anchor" href="#操作步骤" aria-label="Permalink to &quot;操作步骤&quot;">​</a></h5><ol><li><p>打开本地 SSH 客户端工具。</p><p><img src="'+S+'" alt="创建远程连接.png"></p></li><li><p>在连接配置中填写如下信息。</p><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td>名称</td><td>服务器主机名。</td></tr><tr><td>主机地址</td><td>服务器主 IP。</td></tr><tr><td>端口</td><td>端口：默认 SSH 端口为 22；</td></tr><tr><td>方法</td><td>支持密码、公钥和 Keyboard Interactive方式，选择其中一种方式。</td></tr><tr><td>用户名</td><td>root（对应操作系统用户名）。</td></tr><tr><td>密码</td><td>服务器连接密码。可在产品信息邮件中查找对应密码。产品信息邮件会在产品购买开通后由 RakSmart 发送给用户。</td></tr></tbody></table></li><li><p>单击<strong>确定</strong>，远程连接服务器成功如下图所示。</p><p><img src="'+u+'" alt="远程登录成功11.png"></p></li></ol>',26)])])}const k=a(B,[["render",P]]);export{q as __pageData,k as default};
